from pathlib import Path

import pytest

NOTES_DIR = "notes"


def first_readable(names: list[str]) -> str:
    """Return the text of the first name in `names` readable from `notes`.

    Names are untrusted. Only files inside the `notes` directory (relative
    to the working directory) may be read; a name that is missing,
    unreadable, a directory, or that would resolve outside `notes` (via
    `..`, an absolute path, a symlink, etc.) is skipped. Returns an empty
    string when no name can be read.
    """
    try:
        base = Path(NOTES_DIR).resolve()
    except (OSError, ValueError):
        return ""
    for name in names:
        try:
            candidate = (base / name).resolve()
            if candidate == base or not candidate.is_relative_to(base):
                continue
            return candidate.read_text(encoding="utf-8")
        except (OSError, ValueError):
            continue
    return ""


@pytest.fixture
def workdir(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> Path:
    (tmp_path / NOTES_DIR).mkdir()
    (tmp_path / "secret.txt").write_text("TOP SECRET")
    monkeypatch.chdir(tmp_path)
    return tmp_path


def test_returns_first_readable(workdir: Path) -> None:
    (workdir / NOTES_DIR / "a.txt").write_text("alpha")
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["a.txt", "b.txt"]) == "alpha"


def test_skips_missing(workdir: Path) -> None:
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["nope.txt", "b.txt"]) == "beta"


def test_empty_list(workdir: Path) -> None:
    assert first_readable([]) == ""


def test_none_readable(workdir: Path) -> None:
    assert first_readable(["x", "y"]) == ""


def test_notes_dir_missing(tmp_path: Path, monkeypatch: pytest.MonkeyPatch) -> None:
    monkeypatch.chdir(tmp_path)
    assert first_readable(["a.txt"]) == ""


def test_empty_file_is_readable(workdir: Path) -> None:
    (workdir / NOTES_DIR / "empty.txt").write_text("")
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["empty.txt", "b.txt"]) == ""


def test_subdirectory_file_inside_notes(workdir: Path) -> None:
    sub = workdir / NOTES_DIR / "sub"
    sub.mkdir()
    (sub / "c.txt").write_text("gamma")
    assert first_readable(["sub/c.txt"]) == "gamma"


def test_directory_name_skipped(workdir: Path) -> None:
    (workdir / NOTES_DIR / "sub").mkdir()
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["sub", "", ".", "b.txt"]) == "beta"


def test_parent_traversal_rejected(workdir: Path) -> None:
    assert first_readable(["../secret.txt"]) == ""


def test_parent_traversal_skipped_for_later_name(workdir: Path) -> None:
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["../secret.txt", "b.txt"]) == "beta"


def test_deep_traversal_rejected(workdir: Path) -> None:
    (workdir / NOTES_DIR / "sub").mkdir()
    assert first_readable(["sub/../../secret.txt"]) == ""


def test_absolute_path_rejected(workdir: Path) -> None:
    assert first_readable([str(workdir / "secret.txt")]) == ""


def test_absolute_path_into_notes_rejected_or_read(workdir: Path) -> None:
    # An absolute path must never escape; one pointing outside gives "".
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["/etc/passwd", "b.txt"]) == "beta"


def test_symlink_escape_rejected(workdir: Path) -> None:
    link = workdir / NOTES_DIR / "link.txt"
    try:
        link.symlink_to(workdir / "secret.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["link.txt"]) == ""
    assert first_readable(["link.txt", "b.txt"]) == "beta"


def test_symlinked_directory_escape_rejected(workdir: Path) -> None:
    outside = workdir / "outside"
    outside.mkdir()
    (outside / "o.txt").write_text("outside")
    try:
        (workdir / NOTES_DIR / "dirlink").symlink_to(outside, target_is_directory=True)
    except OSError:
        pytest.skip("symlinks not supported")
    assert first_readable(["dirlink/o.txt"]) == ""


def test_symlink_inside_notes_allowed(workdir: Path) -> None:
    (workdir / NOTES_DIR / "real.txt").write_text("real")
    try:
        (workdir / NOTES_DIR / "alias.txt").symlink_to(workdir / NOTES_DIR / "real.txt")
    except OSError:
        pytest.skip("symlinks not supported")
    assert first_readable(["alias.txt"]) == "real"


def test_nul_byte_name_skipped(workdir: Path) -> None:
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    assert first_readable(["a\x00.txt", "b.txt"]) == "beta"


def test_sibling_directory_with_notes_prefix_rejected(workdir: Path) -> None:
    sibling = workdir / "notes_evil"
    sibling.mkdir()
    (sibling / "x.txt").write_text("evil")
    assert first_readable(["../notes_evil/x.txt"]) == ""


def test_unreadable_file_skipped(workdir: Path) -> None:
    import os

    locked = workdir / NOTES_DIR / "locked.txt"
    locked.write_text("hidden")
    locked.chmod(0)
    if os.access(locked, os.R_OK):
        locked.chmod(0o644)
        pytest.skip("cannot make file unreadable (running as root?)")
    (workdir / NOTES_DIR / "b.txt").write_text("beta")
    try:
        assert first_readable(["locked.txt", "b.txt"]) == "beta"
    finally:
        locked.chmod(0o644)
